package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.GradeService; import java.util.List; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1") public class GradeController { private final GradeService service; public GradeController(GradeService s){service=s;} @GetMapping("/grades/answer/{answerId}") public List<GradeResponse> byAnswer(@PathVariable Integer answerId){return service.byAnswer(answerId).stream().map(GradeResponse::from).toList();} @PutMapping("/answers/{answerId}/grade") public GradeResponse update(@PathVariable Integer answerId,@Valid @RequestBody GradeUpdateRequest r){return GradeResponse.from(service.update(answerId,r));} }
